<template>
  <section class="report-page">
    <div class="page-intro"><div><p>OPERATIONS DAILY REPORT</p><h2>运营日报填报</h2><span>用一份结构化日报，完成当天经营复盘与本月目标校准。</span></div><a-date-picker v-model:value="selectedDate" value-format="YYYY-MM-DD" :allow-clear="false" @change="loadData" /></div>
    <div class="identity-strip"><div><small>填报人</small><strong>{{ auth.realName }}</strong></div><div><small>所属部门</small><strong>{{ auth.department || '未配置' }}</strong></div><div><small>填报日期</small><strong>{{ selectedDate }}</strong></div><div><small>表单状态</small><strong :class="existing ? 'success' : ''">{{ existing ? '已提交，可更新' : '待提交' }}</strong></div></div>
    <div class="report-grid">
      <a-form ref="formRef" :model="form" layout="vertical" class="form-card" :disabled="!isToday" @finish="submit">
        <FormSection title="销售与上架" desc="当月累计口径，直接用于目标完成率计算">
          <div class="field-grid"><a-form-item label="累计销售额（USD）" name="cumulative_sales" :rules="requiredNumber"><a-input-number v-model:value="form.cumulative_sales" :min="0" :precision="2" :controls="false" placeholder="请输入金额" /></a-form-item><a-form-item label="实际上架数量" name="listing_count" :rules="requiredNumber"><a-input-number v-model:value="form.listing_count" :min="0" :precision="0" :controls="false" placeholder="请输入数量" /></a-form-item><a-form-item label="产品优化数量" name="optimization_count" :rules="requiredNumber"><a-input-number v-model:value="form.optimization_count" :min="0" :precision="0" :controls="false" placeholder="请输入数量" /></a-form-item></div>
        </FormSection>
        <FormSection title="合规检查" desc="确认当天是否出现平台风险或商品限制">
          <div class="field-grid"><YesNo v-model="form.violation_triggered" label="是否触发违规 / 扣分" name="violation_triggered" variant="risk-violation"/><YesNo v-model="form.infringement_triggered" label="是否链接侵权 / 禁售" name="infringement_triggered" variant="risk-infringement"/><YesNo v-model="form.all_issues_resolved" label="当天问题是否都解决" name="all_issues_resolved" variant="resolved"/></div>
        </FormSection>
        <FormSection title="质量与审核" :desc="isStockingAuditDay ? '今天开放填写备货审核及时率' : '备货审核及时率仅在周一、周三开放，当前只读'">
          <div class="field-grid quality-grid"><a-form-item label="备货审核及时率" name="stocking_audit_rate" :rules="requiredNumber" :class="{ 'field-muted': !isStockingAuditDay }"><a-input-number v-model:value="form.stocking_audit_rate" :disabled="!isStockingAuditDay" :min="0" :max="100" :precision="2" :controls="false" placeholder="0 - 100" addon-after="%" /><span class="field-hint">{{ isStockingAuditDay ? '周一、周三可填写' : '下次开放：周一或周三' }}</span></a-form-item><a-form-item label="产品反推数量" name="reverse_product_count" :rules="requiredNumber"><a-input-number v-model:value="form.reverse_product_count" :min="0" :precision="0" :controls="false" placeholder="请输入数量" /></a-form-item></div>
        </FormSection>
        <FormSection title="店铺业绩波动" desc="只记录上涨或下滑达到 20% 的店铺，有异常时请同步填写店铺名称">
          <div class="variation-panel">
            <div class="variation-panel-head"><div><strong>本周波动记录</strong><span>数量为 0 的方向无需填写店铺名</span></div><div class="variation-summary">共 <b>{{ variationTotal }}</b> 家 · 已填名 <b>{{ variationNamedTotal }}</b> 家 <button type="button" @click="resetVariations">重置</button></div></div>
            <div class="variation-rails">
              <div class="variation-rail variation-rise">
                <div class="variation-badge">上涨</div>
                <a-input-number v-model:value="form.rising_shop_count" class="variation-count" :min="0" :precision="0" :controls="false" placeholder="0" @change="handleVariationCountChange('rising', $event)" />
                <a-input v-if="Number(form.rising_shop_count || 0) > 0" v-model:value="form.rising_shop_names" class="variation-name" placeholder="店铺名1、店铺名2" />
                <span v-else class="variation-empty">数量为 0，本次无需填写</span>
              </div>
              <div class="variation-rail variation-fall">
                <div class="variation-badge">下滑</div>
                <a-input-number v-model:value="form.falling_shop_count" class="variation-count" :min="0" :precision="0" :controls="false" placeholder="0" @change="handleVariationCountChange('falling', $event)" />
                <a-input v-if="Number(form.falling_shop_count || 0) > 0" v-model:value="form.falling_shop_names" class="variation-name" placeholder="店铺名1、店铺名2" />
                <span v-else class="variation-empty">数量为 0，本次无需填写</span>
              </div>
            </div>
            <div class="variation-note">店铺名称可用“、”或逗号分隔，名称数量需与店铺数量一致。</div>
            <div v-if="variationError" class="variation-error">{{ variationError }}</div>
          </div>
        </FormSection>
        <FormSection title="周度项" :desc="isTuesday ? '今天是周二，请完成周度检查' : '仅周二开放填写，当前已自动锁定'">
          <div class="field-grid"><a-form-item label="周延迟率 / 取消率是否超标"><a-radio-group v-model:value="form.weekly_delay_exceeded" :disabled="!isTuesday"><a-radio :value="true">是</a-radio><a-radio :value="false">否</a-radio></a-radio-group></a-form-item><a-form-item label="周商责差评 ≥3 的链接数"><a-input-number v-model:value="form.weekly_bad_review_links" :disabled="!isTuesday" :min="0" :precision="0" :controls="false" placeholder="请输入数量" /></a-form-item><a-form-item label="周错发 / 破损 ≥3 的链接数"><a-input-number v-model:value="form.weekly_wrong_damage_links" :disabled="!isTuesday" :min="0" :precision="0" :controls="false" placeholder="请输入数量" /></a-form-item></div>
        </FormSection>
        <a-button type="primary" html-type="submit" size="large" block :loading="saving" :disabled="!isToday">{{ !isToday ? '仅可提交或修改今日日报' : existing ? '更新今日日报' : '提交今日日报' }}</a-button>
      </a-form>
      <aside class="progress-card"><div class="live"><i></i>本月销售进度</div><div class="progress-number">{{ completionRate }}<span>%</span></div><a-progress :percent="Math.min(Number(completionRate),100)" :show-info="false" :stroke-color="progressColor"/><div class="status-chip" :style="{color:progressColor,background:progressColor+'14'}">{{ statusText }}</div><dl><div><dt>本月目标销售额（USD）</dt><dd>{{ money(target?.sales_target) }}</dd></div><div><dt>当前累计销售额（USD）</dt><dd>{{ money(form.cumulative_sales) }}</dd></div><div><dt>距目标缺口（USD）</dt><dd>{{ money(gap) }}</dd></div><div><dt>时间进度</dt><dd>{{ timeProgress }}%</dd></div></dl><p v-if="!target" class="target-empty">本月目标未配置，请联系管理端。</p></aside>
    </div>
  </section>
</template>
<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref } from 'vue'
import dayjs from 'dayjs'
import { message } from 'ant-design-vue'
import { useAuthStore } from '@/stores/auth'
import { getMyDailyReport, submitDailyReport } from '@/services/api'
const auth=useAuthStore(); const selectedDate=ref(dayjs().format('YYYY-MM-DD')); const saving=ref(false); const existing=ref(false); const target=ref(null); const formRef=ref()
const defaults=()=>({cumulative_sales:null,listing_count:null,optimization_count:null,weekly_delay_exceeded:null,violation_triggered:null,infringement_triggered:null,weekly_bad_review_links:null,weekly_wrong_damage_links:null,stocking_audit_rate:100,reverse_product_count:null,rising_shop_count:null,rising_shop_names:'',falling_shop_count:null,falling_shop_names:'',volatile_store_count:null,all_issues_resolved:null}); const form=reactive(defaults())
const requiredNumber=[{required:true,message:'请填写该项'}]; const isTuesday=computed(()=>dayjs(selectedDate.value).day()===2); const isStockingAuditDay=computed(()=>[1,3].includes(dayjs(selectedDate.value).day())); const completionRate=computed(()=>target.value?.sales_target>0?((Number(form.cumulative_sales||0)/Number(target.value.sales_target))*100).toFixed(1):'0.0'); const gap=computed(()=>Math.max(0,Number(target.value?.sales_target||0)-Number(form.cumulative_sales||0))); const timeProgress=computed(()=>Math.round(dayjs(selectedDate.value).date()/dayjs(selectedDate.value).daysInMonth()*100)); const progressColor=computed(()=>Number(completionRate.value)>=100?'#15a46d':Number(completionRate.value)>=timeProgress.value?'#2f7df4':'#e79531'); const statusText=computed(()=>!target.value?'目标未配置':Number(completionRate.value)>=100?'已超额完成':Number(completionRate.value)>=timeProgress.value?'达标中':'进度落后')
const isToday=computed(()=>selectedDate.value===dayjs().format('YYYY-MM-DD'))
const FormSection=defineComponent({props:['title','desc'],setup(p,{slots}){return()=>h('section',{class:'form-section'},[h('header',[h('h3',p.title),h('p',p.desc)]),slots.default?.()])}}); const YesNo=defineComponent({props:['modelValue','label','name','variant'],emits:['update:modelValue'],setup(p,{emit}){return()=>h('div',{class:['yesno',`yesno-${p.variant}`]},[h('label',p.label),h('div',{class:'toggle'},[h('button',{type:'button',disabled:!isToday.value,class:{'choice-selected':p.modelValue===false,'choice-no':true},onClick:()=>emit('update:modelValue',false)},'否'),h('button',{type:'button',disabled:!isToday.value,class:{'choice-selected':p.modelValue===true,'choice-yes':true},onClick:()=>emit('update:modelValue',true)},'是')]),h('span',{class:['selection-state',p.modelValue===null?'choice-pending':p.modelValue?'choice-state-yes':'choice-state-no']},p.modelValue===null?'待选择':`已选择：${p.modelValue?'是':'否'}`)])}})
function money(v){return `$ ${Number(v||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}`}
function parseShopNames(value){return String(value||'').split(/[,，、\n]+/).map(name=>name.trim()).filter(Boolean)}
function joinShopNames(value){return Array.isArray(value)?value.join('\n'):String(value||'')}
const variationError=computed(()=>{const checks=[['上涨',form.rising_shop_count,form.rising_shop_names],['下滑',form.falling_shop_count,form.falling_shop_names]]; const mismatch=checks.find(([,count,names])=>Number(count||0)!==parseShopNames(names).length); return mismatch?`${mismatch[0]}店铺数量为 ${Number(mismatch[1]||0)} 家，但已填写 ${parseShopNames(mismatch[2]).length} 个店铺名，请保持一致`:''})
const variationTotal=computed(()=>Number(form.rising_shop_count||0)+Number(form.falling_shop_count||0)); const variationNamedTotal=computed(()=>parseShopNames(form.rising_shop_names).length+parseShopNames(form.falling_shop_names).length)
function handleVariationCountChange(kind,value){if(Number(value||0)<=0){if(kind==='rising') form.rising_shop_names=''; else form.falling_shop_names=''}}
function resetVariations(){form.rising_shop_count=0;form.rising_shop_names='';form.falling_shop_count=0;form.falling_shop_names=''}
async function loadData(){const data=await getMyDailyReport(selectedDate.value); target.value=data.target; existing.value=!!data.report; const report=data.report||{}; Object.assign(form,defaults(),report,{rising_shop_names:joinShopNames(report.rising_shop_names),falling_shop_names:joinShopNames(report.falling_shop_names)}); if(!isTuesday.value) Object.assign(form,{weekly_delay_exceeded:null,weekly_bad_review_links:null,weekly_wrong_damage_links:null})}
async function submit(){if(variationError.value){message.error(variationError.value);return} const missingCompliance=[['触发违规 / 扣分',form.violation_triggered],['链接侵权 / 禁售',form.infringement_triggered],['当天问题是否都解决',form.all_issues_resolved]].filter(([,value])=>value===null||value===undefined); if(missingCompliance.length){message.error(`请完成合规检查：${missingCompliance.map(([label])=>label).join('、')}`);return} saving.value=true;try{await submitDailyReport({...form,report_date:selectedDate.value,volatile_store_count:variationTotal.value,rising_shop_count:Number(form.rising_shop_count||0),rising_shop_names:parseShopNames(form.rising_shop_names),falling_shop_count:Number(form.falling_shop_count||0),falling_shop_names:parseShopNames(form.falling_shop_names)});message.success(existing.value?'日报已更新':'日报提交成功');await loadData()}finally{saving.value=false}}
onMounted(loadData)
</script>
