:deep(.yesno-risk-violation .choice-selected.choice-yes),:deep(.yesno-risk-infringement .choice-selected.choice-yes){border-color:#f0a15a;color:#c8751d;background:#fff4e8;box-shadow:0 3px 10px rgba(240,161,90,.18)}
:deep(.yesno-risk-violation .choice-selected.choice-no),:deep(.yesno-risk-infringement .choice-selected.choice-no){border-color:#32ae7a;color:#16845b;background:#eaf9f2;box-shadow:0 3px 10px rgba(50,174,122,.16)}
:deep(.yesno-resolved .choice-selected.choice-yes){border-color:#32ae7a;color:#16845b;background:#eaf9f2;box-shadow:0 3px 10px rgba(50,174,122,.16)}:deep(.yesno-resolved .choice-selected.choice-no){border-color:#f0a15a;color:#c8751d;background:#fff4e8;box-shadow:0 3px 10px rgba(240,161,90,.18)}
:deep(.yesno-risk-violation .choice-state-yes),:deep(.yesno-risk-infringement .choice-state-yes){color:#c8751d}:deep(.yesno-risk-violation .choice-state-no),:deep(.yesno-risk-infringement .choice-state-no){color:#16845b}:deep(.yesno-resolved .choice-state-yes){color:#16845b}:deep(.yesno-resolved .choice-state-no){color:#c8751d}
</style>
